#!/usr/bin/env node
/**
 * Converts the Phoenix app's design tokens into this site's token layer.
 *
 * BRIEF §2.6: design values come only from Phoenix tokens
 * (`/Users/wallex/Phoenix/src/theme`, read-only), converted to CSS custom
 * properties for light and dark. This script is that conversion. It imports
 * `primitives.ts` and `semantic.ts` directly — both are dependency-free — with
 * Node's own type stripping, and writes two generated files:
 *
 *   src/theme/tokens.generated.css   custom properties, dark by default,
 *                                    light under `prefers-color-scheme` and
 *                                    under an explicit `data-theme`
 *   src/theme/tokens.generated.ts    the same values as typed constants, for
 *                                    the 3D scene and anything else that
 *                                    needs a number rather than a `var()`
 *
 * Both generated files are committed, so the site builds anywhere without the
 * app's working tree. Re-run after the app's tokens change:
 *
 *   npm run tokens                       # reads ../Phoenix/src/theme
 *   PHOENIX_THEME_DIR=/path npm run tokens
 *
 * NOTHING IS INVENTED HERE. Every emitted value is one the app's files carry,
 * under a name derived mechanically from the app's own key. Site-only values
 * that the app has no counterpart for live in `src/theme/site-tokens.ts`,
 * each with the reason it exists.
 */

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "../..");
const themeDir = resolve(
  process.env.PHOENIX_THEME_DIR ?? resolve(root, "../Phoenix/src/theme"),
);

const primitives = await import(
  pathToFileURL(resolve(themeDir, "primitives.ts")).href
);
const semantic = await import(
  pathToFileURL(resolve(themeDir, "semantic.ts")).href
);

const {
  palette,
  space,
  radius,
  typography,
  fontFamily,
  blur,
  shadowRamp,
  innerHighlight,
  shadowGeometry,
  border,
  opacity,
} = primitives;
const { semanticColors } = semantic;

/* ------------------------------------------------------------------ naming */

/** `primary.400` → `primary-400`, `whiteA25` → `white-a25`, `a5` → `a5`. */
function kebab(key) {
  return String(key)
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/_/g, "-")
    .toLowerCase();
}

/** Flattens a nested record into `[path[], leaf]` pairs. */
function leaves(value, path = []) {
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    return Object.entries(value).flatMap(([key, child]) =>
      leaves(child, [...path, key]),
    );
  }
  return [[path, value]];
}

/* ----------------------------------------------------------------- weights */

/**
 * The app loads static faces named `Geist_600SemiBold`; the web loads the
 * variable font through `next/font`, so a face becomes a `font-weight`. The
 * number is read out of the app's own face name, not assumed.
 */
function weightOf(face) {
  const match = /_(\d{3})/.exec(face);
  if (match === null)
    throw new Error(`cannot read a weight from face "${face}"`);
  return Number(match[1]);
}

/* -------------------------------------------------------------------- css */

const css = [];
const ts = [];

css.push(
  "/* GENERATED by scripts/tokens/extract.mjs from the Phoenix app's theme. Do not edit. */",
  "",
  ":root {",
);

const paletteVars = [];
for (const [path, value] of leaves(palette)) {
  const name = `--color-${path.map(kebab).join("-")}`;
  paletteVars.push([name, value]);
  css.push(`  ${name}: ${value};`);
}

css.push("");
for (const [key, value] of Object.entries(space)) {
  css.push(`  --space-${kebab(key)}: ${String(value)}px;`);
}
css.push("");
for (const [key, value] of Object.entries(radius)) {
  css.push(`  --radius-${kebab(key)}: ${String(value)}px;`);
}
css.push("");
for (const [key, face] of Object.entries(fontFamily)) {
  if (!face.startsWith("Geist")) continue; // the Persian faces are not used on the site
  css.push(`  --font-weight-${kebab(key)}: ${String(weightOf(face))};`);
}
css.push("");
for (const [key, style] of Object.entries(typography)) {
  if (!style.fontFamily.startsWith("Geist")) continue;
  css.push(`  --text-${kebab(key)}-size: ${String(style.fontSize)}px;`);
  css.push(
    `  --text-${kebab(key)}-weight: ${String(weightOf(style.fontFamily))};`,
  );
}
css.push("");
for (const [key, value] of Object.entries(blur)) {
  css.push(`  --blur-${kebab(key)}: ${String(value)}px;`);
}
css.push("");
for (const [key, ramp] of Object.entries(shadowRamp)) {
  const layers = ramp
    .map(
      (l) =>
        `${String(l.offsetX)}px ${String(l.offsetY)}px ${String(l.blurRadius)}px ${l.color}`,
    )
    .join(", ");
  css.push(`  --shadow-${kebab(key)}: ${layers};`);
}
css.push("");
for (const [key, g] of Object.entries(innerHighlight)) {
  css.push(
    `  --inner-highlight-${kebab(key)}: inset ${String(g.offsetX)}px ${String(g.offsetY)}px ${String(g.blurRadius)}px var(--color-grey-white-a25);`,
  );
}
css.push("");
for (const [key, g] of Object.entries(shadowGeometry)) {
  css.push(
    `  --shadow-geometry-${kebab(key)}: ${String(g.offsetX)}px ${String(g.offsetY)}px ${String(g.blurRadius)}px ${String(g.spreadRadius)}px;`,
  );
}
css.push("", `  --border-width: ${String(border.width)}px;`, "");
for (const [key, value] of Object.entries(opacity)) {
  css.push(`  --opacity-${kebab(key)}: ${String(value)};`);
}
css.push("}", "");

/** Semantic colours for one mode, as declarations. */
function semanticBlock(mode, indent) {
  const lines = [];
  for (const [path, value] of leaves(semanticColors[mode])) {
    lines.push(`${indent}--color-${path.map(kebab).join("-")}: ${value};`);
  }
  /* The composed, mode-aware shadows the app builds in `theme.ts`. */
  const c = semanticColors[mode];
  const sg = shadowGeometry;
  const shadow = (g, color) =>
    `${String(g.offsetX)}px ${String(g.offsetY)}px ${String(g.blurRadius)}px ${String(g.spreadRadius)}px ${color}`;
  lines.push(
    `${indent}--shadow-placeholder: ${shadow(sg.placeholder, c.shadow.placeholder)};`,
  );
  lines.push(
    `${indent}--shadow-floating-card: ${shadow(sg.floatingCard, c.shadow.placeholder)};`,
  );
  lines.push(
    `${indent}--shadow-chip: ${shadow(sg.chip, c.shadow.placeholder)};`,
  );
  lines.push(
    `${indent}--shadow-pending-chip: ${shadow(sg.pendingChip, c.surface.subPlaceholder)};`,
  );
  lines.push(
    `${indent}--shadow-input-focus-glow: ${shadow(sg.inputFocusGlow, palette.primary.a20)};`,
  );
  lines.push(
    `${indent}--shadow-route-strip-inset: inset ${shadow(sg.routeStripInset, palette.secondary.a20)};`,
  );
  lines.push(`${indent}color-scheme: ${mode};`);
  return lines;
}

css.push(
  "/* Dark is the default: the scene is space in both modes (STORYBOARD §5). */",
);
css.push(":root {", ...semanticBlock("dark", "  "), "}", "");
css.push("@media (prefers-color-scheme: light) {");
css.push(
  '  :root:not([data-theme="dark"]) {',
  ...semanticBlock("light", "    "),
  "  }",
);
css.push("}", "");
css.push(
  ':root[data-theme="light"] {',
  ...semanticBlock("light", "  "),
  "}",
  "",
);
css.push(':root[data-theme="dark"] {', ...semanticBlock("dark", "  "), "}", "");

/* --------------------------------------------------------------------- ts */

ts.push(
  "/* GENERATED by scripts/tokens/extract.mjs from the Phoenix app's theme. Do not edit. */",
  "",
  `export const palette = ${JSON.stringify(palette, null, 2)} as const;`,
  "",
  `export const space = ${JSON.stringify(space, null, 2)} as const;`,
  "",
  `export const radius = ${JSON.stringify(radius, null, 2)} as const;`,
  "",
  `export const fontWeight = ${JSON.stringify(
    Object.fromEntries(
      Object.entries(fontFamily)
        .filter(([, face]) => face.startsWith("Geist"))
        .map(([key, face]) => [key, weightOf(face)]),
    ),
    null,
    2,
  )} as const;`,
  "",
  `export const typography = ${JSON.stringify(
    Object.fromEntries(
      Object.entries(typography)
        .filter(([, style]) => style.fontFamily.startsWith("Geist"))
        .map(([key, style]) => [
          key,
          { size: style.fontSize, weight: weightOf(style.fontFamily) },
        ]),
    ),
    null,
    2,
  )} as const;`,
  "",
  `export const blur = ${JSON.stringify(blur, null, 2)} as const;`,
  "",
  `export const opacity = ${JSON.stringify(opacity, null, 2)} as const;`,
  "",
  `export const border = ${JSON.stringify(border, null, 2)} as const;`,
  "",
  `export const semanticColors = ${JSON.stringify(semanticColors, null, 2)} as const;`,
  "",
  "export type ThemeMode = keyof typeof semanticColors;",
  "",
);

/* ------------------------------------------------------------------ write */

const outDir = resolve(root, "src/theme");
mkdirSync(outDir, { recursive: true });
writeFileSync(resolve(outDir, "tokens.generated.css"), css.join("\n") + "\n");
writeFileSync(resolve(outDir, "tokens.generated.ts"), ts.join("\n"));

console.log(
  `Wrote ${String(paletteVars.length)} palette colours, ${String(Object.keys(space).length)} spaces, ` +
    `${String(Object.keys(radius).length)} radii, ${String(Object.keys(typography).length)} text styles, ` +
    `${String(Object.keys(shadowRamp).length)} shadow ramps and ${String(leaves(semanticColors.dark).length)} semantic colours per mode ` +
    `from ${themeDir}`,
);
